BEGIN READ ONLY;
SET LOCAL statement_timeout = '15s';
SELECT jsonb_build_object(
  'captured_at', now(), 'postgres_version', version(),
  'schema_privileges', (SELECT jsonb_agg(jsonb_build_object('role',r,'usage',has_schema_privilege(r,'public','USAGE'),'create',has_schema_privilege(r,'public','CREATE'))) FROM unnest(ARRAY['anon','authenticated','service_role']) r),
  'tables', (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'options',c.reloptions)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m')),
  'columns', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped),
  'constraints', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid,true))) FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'),
  'indexes', (SELECT jsonb_agg(to_jsonb(i)) FROM pg_indexes i WHERE schemaname='public'),
  'policies', (SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='public'),
  'table_privileges', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r,'select',has_table_privilege(r,c.oid,'SELECT'),'insert',has_table_privilege(r,c.oid,'INSERT'),'update',has_table_privilege(r,c.oid,'UPDATE'),'delete',has_table_privilege(r,c.oid,'DELETE'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) r WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m')),
  'functions', (SELECT jsonb_agg(jsonb_build_object('name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f'),
  'triggers', (SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true))) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal),
  'sequences', (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'role',r,'usage',has_sequence_privilege(r,c.oid,'USAGE'),'select',has_sequence_privilege(r,c.oid,'SELECT'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) r WHERE n.nspname='public' AND c.relkind='S'),
  'aggregate_integrity', jsonb_build_object('staff_without_auth', (SELECT count(*) FROM public.staff WHERE active AND terminated_at IS NULL AND auth_user_id IS NULL),'businesses_without_live_owner',(SELECT count(*) FROM public.businesses b WHERE NOT EXISTS(SELECT 1 FROM public.staff s WHERE s.business_id=b.id AND s.active AND s.terminated_at IS NULL AND s.role='owner')),'pending_reconciliations',(SELECT count(*) FROM public.auth_reconciliation WHERE state='pending'))
) AS audit_catalog;
ROLLBACK;
